sql_calls.sql:
SELECT sku, name, pack, case_kg
FROM store.products
WHERE name ILIKE '%atta%' AND pack ILIKE '%5%kg%';

SELECT p.sku, p.name, p.pack, p.case_units
FROM store.products p
WHERE p.sku = 'ATTA-WW-5KG';

SELECT *
FROM store.shelf_audits
LIMIT 20;

SELECT table_name
FROM information_schema.tables
WHERE table_schema = 'store' AND table_name LIKE '%competitor%';

SELECT DISTINCT tender, till_status
FROM payments.pos_payments
ORDER BY tender, till_status;

SELECT *
FROM store.pos_lines
LIMIT 20;

SELECT *
FROM payments.psp_upi_report
LIMIT 20;

SELECT *
FROM payments.upi_refunds
LIMIT 20;

SELECT DISTINCT kind, resolution
FROM payments.customer_complaints
ORDER BY kind, resolution;

SELECT DISTINCT till_status
FROM payments.pos_payments
ORDER BY till_status;

SELECT SUM(revenue_inr) AS total_sales_may_2026
FROM store.daily_sales
WHERE date >= '2026-05-01' AND date < '2026-06-01';

SELECT COUNT(*) AS shipments_arrived_may_2026
FROM warehouse.shipments
WHERE arrived_ts >= '2026-05-01' AND arrived_ts < '2026-06-01';

SELECT DISTINCT tender
FROM payments.pos_payments
ORDER BY tender;

SELECT DISTINCT trigger
FROM store.stock_counts
ORDER BY trigger;

SELECT column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'warehouse' AND table_name = 'shipments';

SELECT column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'payments' AND table_name = 'customer_complaints';

SELECT column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'store' AND table_name = 'products';

SELECT column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'store' AND table_name = 'pos_lines';

SELECT SUM(amount_inr) AS total_refund_amount
FROM payments.upi_refunds
WHERE date_trunc('month', completed_ts) = '2026-06-01';

SELECT *
FROM payments.customer_complaints
WHERE date_trunc('month', complaint_ts) = '2026-06-01';

SELECT sku, name
FROM store.products
WHERE name ILIKE '%toned%milk%' OR name ILIKE '%milk%toned%';

SELECT COUNT(*) as grn_lines
FROM store.goods_receipts
WHERE received_ts >= '2026-06-01' AND received_ts < '2026-07-01';

SELECT COUNT(DISTINCT date) as writeoff_days
FROM store.write_offs
WHERE date >= '2026-06-01' AND date < '2026-07-01';
